import{_ as o,C as r,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Refuse reasons","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/setup/refuse-reasons.md","filePath":"master/human-resources/recruitment/setup/refuse-reasons.md","lastUpdated":1793074831000}'),l={name:"master/human-resources/recruitment/setup/refuse-reasons.md"};function p(d,e,u,h,c,m){const a=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="refuse-reasons" tabindex="-1">Refuse reasons <a class="header-anchor" href="#refuse-reasons" aria-label="Permalink to &quot;Refuse reasons&quot;">​</a></h1><p>A refuse reason explains why you turned down an application. You pick one every time you refuse an applicant. Each reason is tied to an email template, so the applicant receives the right message when you choose to notify them.</p><blockquote><p><strong>In simple words:</strong> A refuse reason is the &quot;why&quot; behind a refusal, and it decides which email the applicant gets.</p></blockquote><p>Open <code>Recruitments → Configuration → Refuse Reasons</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>None. Seven reasons come with the sample data. Add your own only if you need them.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has the columns <strong>Name</strong> and <strong>Template</strong>. The <strong>Template</strong> column shows the template code, <strong>applicant-refuse</strong> or <strong>applicant-not-interested</strong>. You can search by name, drag rows to reorder them, and open <strong>View</strong>, <strong>Edit</strong> or <strong>Delete</strong> on a row.</p>',7)),s(a,{src:"/images1/recruitment/set_refuse_list.png",alt:"Refuse Reasons list with the Name and Template columns"}),e[1]||(e[1]=t('<h2 id="create-a-refuse-reason" tabindex="-1">Create a refuse reason <a class="header-anchor" href="#create-a-refuse-reason" aria-label="Permalink to &quot;Create a refuse reason&quot;">​</a></h2><p>This example adds <strong>Overqualified</strong>.</p><ol><li>Open <code>Recruitments → Configuration → Refuse Reasons</code>.</li><li>Click <strong>New Refuse Reasons</strong>. A <strong>Create Refuse Reasons</strong> window opens.</li><li>Type <strong>Overqualified</strong> in <strong>Name</strong>.</li><li>Choose <strong>Applicant Refuse</strong> in <strong>Template</strong>.</li><li>Click <strong>Create</strong>. Use <strong>Create &amp; create another</strong> to add more.</li></ol>',3)),s(a,{src:"/images1/recruitment/set_refuse_create.png",alt:"Create Refuse Reasons window with Name Overqualified and Template Applicant Refuse"}),e[2]||(e[2]=t('<ul><li><strong><em>Name:</em></strong> (required) the reason as your team will read it.</li><li><strong><em>Template:</em></strong> (required) the email that goes with the reason.</li></ul><h3 id="which-template-to-choose" tabindex="-1">Which template to choose <a class="header-anchor" href="#which-template-to-choose" aria-label="Permalink to &quot;Which template to choose&quot;">​</a></h3><ul><li><strong>Applicant Refuse:</strong> use it when you turn the applicant down. The email says the profile is competitive but was not selected.</li><li><strong>Applicant Not Interested:</strong> use it when the applicant withdrew. The email thanks the person, keeps the resume on record and promises to be in touch about future roles.</li></ul><p>You cannot edit the email text. It is fixed per template.</p><h2 id="sample-reasons" tabindex="-1">Sample reasons <a class="header-anchor" href="#sample-reasons" aria-label="Permalink to &quot;Sample reasons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reason</th><th>Template</th></tr></thead><tbody><tr><td>Does not fit the job requirements</td><td>Applicant Refuse</td></tr><tr><td>Job already fulfilled</td><td>Applicant Refuse</td></tr><tr><td>Duplicate</td><td>Applicant Refuse</td></tr><tr><td>Discrepancy In Documentation</td><td>Applicant Refuse</td></tr><tr><td>Refused by applicant: job fit</td><td>Applicant Not Interested</td></tr><tr><td>Refused by applicant: salary</td><td>Applicant Not Interested</td></tr><tr><td>Spam</td><td>Applicant Not Interested</td></tr></tbody></table><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>On the <strong>Refuse</strong> window, <strong>Notify</strong> is on by default after you pick a reason. <strong>Email To</strong> starts with the candidate&#39;s email. When you submit, the applicant is refused and the email of the reason&#39;s template is sent.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../applicants/refuse-and-reopen.html">Refuse and reopen</a></li><li><a href="./../applicants/process-applicant.html">Process an applicant</a></li><li><a href="./">Setup overview</a></li></ul>',10))])}const _=o(l,[["render",p]]);export{g as __pageData,_ as default};
